Camera camera = renderingData.cameraData.camera;
if (camera != null && camera.cameraType == CameraType.Reflection)
    return;

_reflectionCamera.cameraType = CameraType.Reflection;
_reflectionCamera.cullingMask = _reflectionMask;
_reflectionCamera.clearFlags = _reflectSkybox
    ? CameraClearFlags.Skybox : CameraClearFlags.SolidColor;
_reflectionCamera.backgroundColor = Color.black;

_reflectionCamera.worldToCameraMatrix =
    sourceCamera.worldToCameraMatrix * reflectionMatrix;
Vector4 clipPlane = CameraSpacePlane(
    _reflectionCamera, planePosition, planeNormal, 1.0f);
_reflectionCamera.projectionMatrix =
    _reflectionCamera.CalculateObliqueMatrix(clipPlane);

RenderPipeline.SubmitRenderRequest(_reflectionCamera, request);
GL.invertCulling = previousInvertCulling;

RenderTexture textureForWater = _reflectionTexture;
if (_smearOn
    && _smearedReflectionTexture != null
    && TryGetSmearMaterial(out Material smearMaterial))
{
    ApplyWatercolorSmear(
        _reflectionTexture, _smearedReflectionTexture, smearMaterial);
    textureForWater = _smearedReflectionTexture;
}

_waterRenderer.GetPropertyBlock(_propertyBlock);
_propertyBlock.SetTexture(ReflectionTextureId, textureForWater);
_waterRenderer.SetPropertyBlock(_propertyBlock);

float Progress = (float)SampleIndex / (SampleCount - 1.0);
float JitterNoise = Hash21(
    BrushCell + float2(SampleIndex * 1.73, SampleIndex * 0.37)) * 2.0 - 1.0;

float2 SampleUV = UV + float2(
    JitterNoise * HorizontalSpan * (0.25 + Progress * 0.75),
    VerticalSpan * Progress);

float ValidSample = IsInsideTexture(SampleUV);
float SampleWeight = lerp(1.0, 0.12, Progress) * ValidSample;
half4 SampledColor = SAMPLE_TEXTURE2D(
    _MainTex, sampler_MainTex, saturate(SampleUV));

WeightedColor += SampledColor * SampleWeight;
TotalWeight += SampleWeight;
PigmentColor = max(PigmentColor,
    lerp(RawReflection, SampledColor, ValidSample));

